sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_styleI;
uniform float amzp_gridPattern;
uniform float amzp_gridStrength;
uniform float amzp_gridColor;
uniform float amzp_gridScale;
uniform float amzp_scanlines;
uniform float amzp_rgbSplit;
uniform float amzp_ghost;
uniform float2 amzp_ghostOff;
uniform float amzp_colorBar;
uniform float amzp_barPosition;
uniform float amzp_barHeight;
uniform float amzp_exposureFix;
uniform float amzp_noiseLevel;
uniform float amzp_vibrance;
uniform float amzp_sharpness;
uniform float amzp_glow;
uniform float amzp_colorize;
uniform float amzp_glitches;
uniform float amzp_glitchAmount;
uniform float amzp_tvBorders;
uniform float amzp_borderCurve;
uniform float amzp_intensity;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float3 unpre(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float hsh(float2 p) { float3 p3 = fract(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
    float rnd(float2 co) { return fract(sin(mod(dot(co, float2(12.9898, 78.233)), 3.14159265)) * 43758.5453); }
    float3 hsv2rgb(float3 c) { float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0); float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www); return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y); }
    float2 barrelWarp(float2 uv, float aspect, float k) { float2 d = uv - 0.5; d.x *= aspect; d *= 1.0 + k * dot(d, d) * 2.0; d.x /= aspect; return 0.5 + d; }
    float3 smp(float2 uv) { return unpre(layerClamp(uv)); }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        int style = int(amzp_styleI) + 1;
        float T = TT();
        float aspect = W.x / W.y;
        float2 uv0 = amzLayerNorm();
        float3 tint = float3(1.0), glowTint = float3(1.0);
        float con = 1.06, satB = 0.0, brightB = 0.0, styleAber = 0.006, styleGlow = 0.12;
        if (style == 1) { con = 1.05; styleAber = 0.005; styleGlow = 0.10; }
        else if (style == 2) { tint = float3(1.08, 1.0, 0.90); satB = 0.06; glowTint = float3(1.1, 0.95, 0.8); styleAber = 0.008; styleGlow = 0.14; }
        else if (style == 3) { con = 1.22; satB = -0.30; styleAber = 0.004; styleGlow = 0.10; }
        else if (style == 4) { tint = float3(0.90, 1.00, 1.05); con = 1.10; satB = 0.10; glowTint = float3(0.6, 0.9, 1.0); styleAber = 0.0025; styleGlow = 0.30; }
        else if (style == 5) { styleGlow = 0.10; }
        else if (style == 6) { tint = float3(0.70, 1.18, 0.80); con = 1.12; satB = 0.12; glowTint = float3(0.3, 1.1, 0.4); styleGlow = 0.35; }
        else if (style == 7) { tint = float3(1.12, 0.85, 1.10); con = 1.10; satB = 0.12; glowTint = float3(1.1, 0.4, 1.0); styleAber = 0.009; styleGlow = 0.38; }
        else if (style == 8) { tint = float3(1.14, 0.98, 0.72); con = 1.04; satB = -0.18; glowTint = float3(1.1, 0.9, 0.6); styleGlow = 0.16; }
        else if (style == 9) { con = 1.34; satB = 0.05; }
        else if (style == 10) { tint = float3(0.72, 1.02, 1.06); con = 1.12; satB = 0.10; glowTint = float3(0.4, 1.05, 1.05); styleAber = 0.009; styleGlow = 0.40; }
        else if (style == 11) { tint = float3(0.95, 0.85, 1.18); con = 1.12; satB = 0.10; glowTint = float3(0.7, 0.4, 1.2); styleAber = 0.010; styleGlow = 0.40; }
        else if (style == 12) { tint = float3(0.92, 0.96, 1.06); con = 1.18; satB = 0.12; brightB = 0.05; glowTint = float3(1.0, 0.6, 1.0); styleAber = 0.012; styleGlow = 0.50; }
        float ga = amzp_glitchAmount / 100.0;
        float2 suv = uv0;
        if (int(amzp_glitches) == 2) suv.x += ga * 0.03 * sin(uv0.y * 130.0 + T * 9.0);
        else if (int(amzp_glitches) == 3) suv.y = fract(suv.y - (0.15 + ga * 0.8) * T);
        else if (int(amzp_glitches) == 4) {
            float2 bc = floor(uv0 * float2(18.0, 14.0));
            if (rnd(bc + floor(T * 12.0)) > 1.0 - ga * 0.6) suv.x += (rnd(bc + 1.7) - 0.5) * ga * 0.12;
        }
        if ((amzp_tvBorders>0.5)) suv = barrelWarp(suv, aspect, amzp_borderCurve);
        float aber = styleAber * amzp_rgbSplit + (int(amzp_glitches) == 1 ? ga * 0.025 : 0.0);
        float2 ro = float2(aber, 0.0);
        float4 cg = layerClamp(suv);
        float3 col = float3(smp(suv + ro).r, unpre(cg).g, smp(suv - ro).b);
        float alpha = cg.a;
        if (amzp_ghost > 0.001) {
            float2 go = float2(amzp_ghostOff.x, -amzp_ghostOff.y) * pxs() / W;
            col = max(col, max(smp(suv + go), smp(suv - go)) * amzp_ghost);
        }
        if (amzp_sharpness > 0.5) {
            float2 sp = 1.5 * pxs() / W;
            float3 bl = (smp(suv + float2(sp.x, 0.0)) + smp(suv - float2(sp.x, 0.0)) + smp(suv + float2(0.0, sp.y)) + smp(suv - float2(0.0, sp.y))) * 0.25;
            col += (col - bl) * (amzp_sharpness / 100.0) * 2.0;
        }
        float amzSource_gl = amzp_glow / 100.0 + styleGlow;
        if (amzSource_gl > 0.001) {
            float2 d = float2(0.006 + amzSource_gl * 0.012) * float2(1.0, aspect);
            float3 b = smp(suv + float2(d.x, 0.0)) + smp(suv - float2(d.x, 0.0)) + smp(suv + float2(0.0, d.y)) + smp(suv - float2(0.0, d.y))
                   + smp(suv + d * 0.7) + smp(suv + float2(-d.x, d.y) * 0.7);
            col += max(b / 6.0 - 0.5, 0.0) * glowTint * amzSource_gl * 1.6;
        }
        if (amzp_gridStrength > 0.001) {
            float gAmt = mix(0.65, 1.0, smoothstep(0.0, 0.12, luma(col)));
            float cell = max(3.0, (W.x / 150.0) / amzp_gridScale);
            float sub = cell / 3.0;
            float xpx = uv0.x * W.x, ypx = uv0.y * W.y;
            float ci = floor(mod(xpx / sub, 3.0));
            float3 m = ci < 0.5 ? float3(1.0, 0.0, 0.0) : (ci < 1.5 ? float3(0.0, 1.0, 0.0) : float3(0.0, 0.0, 1.0));
            m = mix(float3(1.0), m * 3.0, amzp_gridColor);
            float prof;
            if (int(amzp_gridPattern) == 0) { float2 dd = float2(fract(xpx / sub) - 0.5, fract(ypx / cell) - 0.5); prof = 0.45 + 0.55 * (1.0 - smoothstep(0.30, 0.62, length(dd))); }
            else { prof = 0.5 + 0.5 * (0.5 + 0.5 * cos(6.2831853 * (fract(xpx / sub) - 0.5))); }
            prof /= 0.75;
            col = mix(col, col * m * prof, amzp_gridStrength * gAmt);
        }
        if (amzp_scanlines > 0.001) {
            float sg = smoothstep(0.05, 0.40, luma(col));
            float spch = max(2.0, (W.y / 220.0) * amzp_gridScale);
            float sl0 = 0.5 + 0.5 * cos(6.2831853 * uv0.y * W.y / spch);
            col *= 1.0 - amzp_scanlines * 0.6 * sg * (1.0 - sl0);
            col *= 1.0 + amzp_scanlines * 0.22 * sg;
        }
        col *= tint;
        col = (col - 0.5) * con + 0.5 + brightB;
        col *= pow(2.0, amzp_exposureFix / 100.0);
        {
            float y = luma(col);
            float cs = max(max(col.r, col.g), col.b) - min(min(col.r, col.g), col.b);
            col = clamp(mix(float3(y), col, 1.0 + (amzp_vibrance / 100.0) * (1.0 - cs * 0.7) + satB), 0.0, 1.0);
        }
        if (style == 10) {
            float a = radians(amzp_colorize);
            float3 k = float3(0.57735);
            col = clamp(col * cos(a) + cross(k, col) * sin(a) + k * dot(k, col) * (1.0 - cos(a)), 0.0, 1.0);
        }
        if (amzp_noiseLevel > 0.5) {
            float dg = 1.0 - smoothstep(0.02, 0.35, luma(col));
            float n = rnd(floor(uv0 * W / 2.0) + float2(floor(T * 24.0)));
            col = mix(col, float3(n), (amzp_noiseLevel / 10.0) * 0.35 * dg);
        }
        if ((amzp_colorBar>0.5) && amzp_barHeight > 0.001) {
            float inBar = int(amzp_barPosition) == 0 ? step(1.0 - amzp_barHeight, uv0.y) : step(uv0.y, amzp_barHeight);
            if (inBar > 0.5) { col = hsv2rgb(float3(max(0.0, 0.667 * (1.0 - uv0.x / 0.75)), 1.0, 1.0)); alpha = max(alpha, orig.a); }
        }
        if ((amzp_tvBorders>0.5)) {
            float2 dl = barrelWarp(uv0, aspect, amzp_borderCurve);
            float2 q = abs(dl - 0.5) * 2.0;
            float2 dd = max(q - float2(0.92), 0.0);
            dd.x *= aspect;
            float em = 1.0 - smoothstep(0.08, 0.10, length(dd));
            float ins = step(0.0, dl.x) * step(dl.x, 1.0) * step(0.0, dl.y) * step(dl.y, 1.0);
            alpha *= em * ins;
            float2 vq = (dl - 0.5) * 2.0;
            col *= 1.0 - 0.35 * smoothstep(0.4, 1.7, dot(vq, vq));
        }
        col = clamp(col, 0.0, 1.0);
        float4 res = float4(col * alpha, alpha);
        float4 R = mix(orig, res, amzp_intensity);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
